using Microsoft.EntityFrameworkCore.Storage;
using WebApolice.Modulos.Cadastro.Application.Ports;  namespace WebApolice.Modulos.Cadastro.Infrastructure.Persistence;  public class CadastroTransactionManager : ICadastroTransactionManager {     private readonly CadastroDbContext _dbContext;      public CadastroTransactionManager(CadastroDbContext dbContext)     {         _dbContext = dbContext;     }      public async Task<System.Data.Common.DbTransaction> BeginTransactionAsync(CancellationToken cancellationToken = default)     {         var transaction = await _dbContext.Database.BeginTransactionAsync(cancellationToken);         return transaction.GetDbTransaction();     } }
